style.css:
@-moz-document domain("google.com"), domain("userstyles.org"), regexp(".*") {
/* --- COLOR PALETTE FROM IMAGE --- */
    :root {
        --ssc-bg-dark: #07060f;
        --ssc-bg-card: #0e0c1b;
        --ssc-purple-glow: #8b5cf6;
        --ssc-silver-light: #e0e7ff;
        --ssc-chain-steel: #332d4f;
        --ssc-text-main: #f1f5f9;
        --ssc-text-muted: #94a3b8;
    }

    /* --- GLOBAL BACKGROUND & OVERLAYS --- */
    body {
        background-color: var(--ssc-bg-dark) !important;
        color: var(--ssc-text-main) !important;
    }

    /* --- CARDS, PANELS & CONTAINER STYLING --- */
    div, section, article, header, nav, aside {
        background-color: var(--ssc-bg-card) !important;
        border-color: var(--ssc-chain-steel) !important;
        color: var(--ssc-text-main) !important;
    }

    /* --- LINKS & GLOWING ACCENTS --- */
    a, a:visited {
        color: #c084fc !important;
        text-shadow: 0 0 6px rgba(139, 92, 246, 0.4) !important;
        transition: all 0.2s ease !important;
    }

    a:hover {
        color: var(--ssc-silver-light) !important;
        text-shadow: 0 0 12px rgba(192, 132, 252, 0.9) !important;
    }

    h1, h2, h3, h4, h5, h6 {
        color: var(--ssc-silver-light) !important;
        text-transform: uppercase !important;
        letter-spacing: 1px !important;
        border-bottom: 1px solid var(--ssc-chain-steel) !important;
    }

    /* --- SEARCH BAR & INPUT FIELDS --- */
    input, textarea, select, button {
        background-color: #131024 !important;
        color: var(--ssc-silver-light) !important;
        border: 1px solid var(--ssc-purple-glow) !important;
        border-radius: 20px !important;
        box-shadow: 0 0 8px rgba(139, 92, 246, 0.2) !important;
    }

    input:focus, textarea:focus {
        border-color: #c084fc !important;
        box-shadow: 0 0 15px rgba(192, 132, 252, 0.5) !important;
        outline: none !important;
    }

    /* --- BUTTONS --- */
    button, input[type="submit"], input[type="button"] {
        background: linear-gradient(180deg, #251d45 0%, #100b24 100%) !important;
        border-radius: 8px !important;
        cursor: pointer !important;
        font-weight: 600 !important;
    }

    button:hover, input[type="submit"]:hover {
        background: linear-gradient(180deg, #4c1d95 0%, #251d45 100%) !important;
        border-color: #c084fc !important;
        box-shadow: 0 0 12px rgba(192, 132, 252, 0.6) !important;
    }

    /* --- SCROLLBAR (MATCHING STAINED GLASS/STEEL) --- */
    ::-webkit-scrollbar {
        width: 10px !important;
        height: 10px !important;
        background-color: var(--ssc-bg-dark) !important;
    }

    ::-webkit-scrollbar-track {
        background: var(--ssc-bg-dark) !important;
        border-left: 1px solid var(--ssc-chain-steel) !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(180deg, #4c1d95 0%, #131024 100%) !important;
        border: 1px solid var(--ssc-purple-glow) !important;
        border-radius: 4px !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: var(--ssc-purple-glow) !important;
        box-shadow: 0 0 8px rgba(192, 132, 252, 0.8) !important;
    }

    /* --- TEXT SELECTION --- */
    ::selection {
        background-color: #581c87 !important;
        color: #ffffff !important;
    }
}
